import {imageData,videoData} from './intake-media.js';
import {createCaptureController} from './capture.js';
import {createPressToTalk} from './press-to-talk.js';
import {createOnboardingSpeech} from './onboarding-speech.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createIntakeUI({api,exampleMode,root,redraw,onDone}){
 let s,epoch=0,active=false,recordingStarted=false;
 const speech=createOnboardingSpeech();
 const capture=createCaptureController({onChange(){updateRecording();},onError(message){s.error=message;updateRecording();}});
 const talk=createPressToTalk({capture,onChange:updateRecording,onSend:transcribe});
 function reset(){stop();s={step:'capture',photos:[],video:null,document:null,text:'',turns:[],answer:'',draft:null,error:'',busy:false,key:crypto.randomUUID(),commit:null};active=true;}
 function stop(){active=false;epoch++;talk.cancel();speech.cancel();capture.emergencyStop();}
 function updateRecording(){if(!active)return;const button=root.querySelector('#intake-hold'),live=root.querySelector('#intake-live');if(button){button.classList.toggle('recording',talk.state.holding);button.classList.toggle('cancel-recording',talk.state.cancelling);button.textContent=talk.state.cancelling?'松手取消':talk.state.holding?'松开发送 · 上滑取消':talk.state.finishing?'正在转写…':'按住说话';}if(live)live.textContent=talk.state.live||s.error||(talk.state.holding?'正在听，最长 60 秒…':'');if(capture.media.voiceRecorder)recordingStarted=true;if(recordingStarted&&talk.state.holding&&!capture.media.voicePending&&!capture.media.voiceRecorder&&capture.media.audioUrl)void talk.end();}
 async function transcribe(url){const ticket=epoch;const r=await speech.transcribe(url);if(!active||ticket!==epoch||!r)return;if(r.error)s.error=r.error;else{s.answer=r.text;s.error='';}redraw();}
 function images(){return [...s.photos.slice(0,2).map(dataUrl=>({kind:'photo',dataUrl})),...(s.video?.frames||[]).map(dataUrl=>({kind:'video',dataUrl})),...(s.document?[{kind:'document',dataUrl:s.document}]:[])];}
 const button=(label,action,cls='button secondary',extra='')=>`<button type="button" class="${cls}" data-intake="${action}" ${s.busy?'disabled':''} ${extra}>${label}</button>`;
 function render(){active=true;if(!s)reset();const d=s.draft;
  const attachments=s.photos.map((p,i)=>`<figure><img src="${p}" alt="上传的宠物照片 ${i+1}">${!s.commit?button('移除','remove-photo','text-button',`data-index="${i}"`):''}</figure>`).join('')+(s.video?`<figure><video src="${s.video.dataUrl}" controls playsinline></video>${!s.commit?button('移除视频','remove-video','text-button'):''}</figure>`:'');
  const confirmation=d?`<article class="intake-confirm-card"><span class="live-tag">档案草稿 · 等你确认</span><h2>${esc(d.name||'还不知道它的名字')}</h2><p class="online-note">${d.species==='cat'?'猫咪':d.species==='dog'?'狗狗':'类别待确认'} · ${esc(d.age||'年龄待确认')}</p><p>${esc(d.description||'更多日常等你告诉我。')}</p>${d.uncertainties?.length?`<p class="intake-unknown">还待了解：${d.uncertainties.map(esc).join('；')}</p>`:''}<form id="intake-confirm"><fieldset class="intake-fields" ${s.commit?'disabled':''}><details><summary>直接修改文字</summary>${['name','age','character'].map(k=>`<label>${{name:'名字',age:'年龄及依据',character:'性格观察'}[k]}<input name="${k}" maxlength="${k==='character'?500:80}" value="${esc(d[k])}"></label>`).join('')}<label>类别<select name="species">${[['unknown','待确认'],['cat','猫咪'],['dog','狗狗']].map(([v,l])=>`<option value="${v}" ${d.species===v?'selected':''}>${l}</option>`).join('')}</select></label><label>性别<select name="sex">${[['unknown','待确认'],['male','男孩子'],['female','女孩子']].map(([v,l])=>`<option value="${v}" ${d.sex===v?'selected':''}>${l}</option>`).join('')}</select></label><label>档案文字<textarea name="description" rows="4" maxlength="4000">${esc(d.description)}</textarea></label></details>${d.ocrText?`<details><summary>材料识别文字 · 仅本站可见</summary><p class="source-text">${esc(d.ocrText)}</p><small>核对原件后，可以告诉我哪些内容需要补充进档案。</small></details>`:''}<label class="check-label"><input type="checkbox" name="published" ${s.published?'checked':''}><span>同时向领养者展示<small>默认仅保存到本站</small></span></label></fieldset><button class="button primary full" ${s.busy?'disabled':''}>${s.busy?'正在保存…':s.commit?'重试保存同一份档案':'确认，建立档案'}</button></form></article>`:'';
  return `<section class="intake-flow intake-chat-flow"><div class="intake-agent-heading"><span>✦</span><div><strong>建档小助手</strong><small>${exampleMode?'预设示例 · 不调用真实 AI':'拍下它，聊聊它，我来整理'}</small></div></div><div class="intake-conversation"><div class="chat-bubble">先发一张照片或一段视频吧。再告诉我它叫什么、平时怎么样，不清楚的可以先跳过。</div>${attachments?`<div class="intake-attachment-message"><div class="intake-media">${attachments}</div><small>你上传的素材${exampleMode?' · 示例':''}</small></div>`:''}${s.document?`<div class="chat-bubble mine">已添加一张材料图片 · 仅本站可见 ${!s.commit?button('移除','remove-document','text-button'):''}</div>`:''}${s.turns.map(t=>`<div class="chat-bubble ${t.role==='user'?'mine':''}">${esc(t.text)}</div>`).join('')}${confirmation}${d?.nextQuestion?`<div class="chat-bubble">${esc(d.nextQuestion)}${!s.commit?button('暂时不清楚','unknown','text-button'):''}</div>`:d?'<div class="chat-bubble">这是目前整理好的档案。可以直接确认，也可以继续说需要补充或更正的地方。</div>':attachments?'<div class="chat-bubble">收到啦。按住下面的按钮，说说你认识的它。</div>':''}<p class="online-error" role="alert">${esc(s.error)}</p>${s.busy?'<p role="status">正在整理，请稍候…</p>':''}</div><div class="intake-composer"><div class="intake-attach-tools">${button('拍照','camera','text-button',s.commit?'disabled':'')}${button('视频','video','text-button',s.commit?'disabled':'')}${button('相册','album','text-button',s.commit?'disabled':'')}${button('材料','document','text-button',s.commit?'disabled':'')}${button('打字','keyboard','text-button',s.commit?'disabled':'')}${exampleMode?button('示例','sample','text-button'):''}</div><input hidden id="intake-camera" type="file" accept="image/*" capture="environment"><input hidden id="intake-album" type="file" accept="image/jpeg,image/png,image/webp" multiple><input hidden id="intake-video" type="file" accept="video/mp4,video/webm" capture="environment"><input hidden id="intake-document" type="file" accept="image/*">${exampleMode?button('使用示例回答','sample-answer','button secondary full'):s.commit?'':'<button type="button" id="intake-hold" class="online-voice">按住说话</button>'}<p id="intake-live" class="intake-live" aria-live="polite"></p>${s.answer||s.keyboard?`<div class="intake-text-compose"><label class="sr-only" for="intake-answer">确认转写或输入文字</label><textarea id="intake-answer" rows="2" maxlength="4000" placeholder="输入想告诉我的内容…" ${s.commit?'disabled':''}>${esc(s.answer)}</textarea>${button('发送','analyze','button primary',s.commit?'disabled':'')}</div><small>核对文字后发送 · 可直接修改</small>`:'<small>松手转写，上滑取消 · 最长 60 秒</small>'}${capture.media.audioUrl?`<details><summary>回听录音 / 重试转写</summary><audio controls src="${capture.media.audioUrl}"></audio>${button('重新转写','retry-speech','text-button')}</details>`:''}</div></section>`;
 }
 function remember(){const a=root.querySelector('#intake-answer');if(a)s.answer=a.value;const f=root.querySelector('#intake-confirm');if(f&&s.draft&&!s.commit){const data=new FormData(f);s.published=data.has('published');for(const k of ['name','species','description','age','character','sex'])s.draft[k]=String(data.get(k)||'');}}
 async function analyze(unknown=false){remember();if(!unknown&&!s.answer.trim()){s.error='先说一段，或输入你了解的情况。';redraw();return;}const question=s.draft?.nextQuestion||(s.draft?'还有哪些补充或更正？':'请介绍这位伙伴');const answer=unknown?'这项不清楚，先保留待确认。':s.answer.trim();const text=[s.text,`助手提问：${question}\n救助者口述：${answer}`].filter(Boolean).join('\n');if(text.length>12000)throw Error('这次口述内容较多，请先确认已有档案，再补充日常。');const result=await api.draftIntake({text,images:images()});s.text=text;s.turns.push({role:'assistant',text:question},{role:'user',text:answer});s.draft=result;s.answer='';await capture.reset();if(!result.nextQuestion)s.step='review';}
 async function action(e){const b=e.target.closest('[data-intake]');if(!b||b.disabled||s.busy||talk.state.holding||talk.state.finishing)return;const a=b.dataset.intake;if(s.commit&&!['retry-speech'].includes(a))return;remember();if(['camera','album','video','document'].includes(a)){root.querySelector('#intake-'+a).click();return;}s.error='';
  if(a==='retry-speech'){await transcribe(capture.media.audioUrl);return;}
  const ticket=epoch,previousStep=s.step;s.busy=true;
  try{if(a==='remove-photo'){s.photos.splice(Number(b.dataset.index),1);s.draft=null;}else if(a==='remove-video'){s.video=null;s.draft=null;}else if(a==='remove-document'){s.document=null;s.draft=null;}
   else if(a==='sample'){const r=await fetch('./assets/orange.jpg');if(!r.ok)throw Error('示例照片暂不可用');s.photos=[await imageData(await r.blob())];s.answer='它叫小满，平时喜欢逗猫棒，年龄不清楚。';}
   else if(a==='sample-answer')s.answer=s.draft?'目前没有检查报告，健康情况还需要确认。':'它叫小满，平时喜欢玩羽毛逗猫棒，估计一岁，具体生日不清楚。';
   else if(a==='keyboard'){s.keyboard=!s.keyboard;}
   else if(a==='more'){s.step='describe';s.commit=null;s.key=crypto.randomUUID();s.draft.nextQuestion='还有哪些你想补充或更正的情况？';}
   else if(a==='review')s.step='review';
   else if(a==='analyze'||a==='unknown'){redraw();await analyze(a==='unknown');}
  }catch(err){s.error=err.message;}finally{if(active&&ticket===epoch){s.busy=false;redraw();}}
 }
 async function change(e){const el=e.target;if(!el.id?.startsWith('intake-')||el.type!=='file'||!el.files?.length)return;s.busy=true;s.error='';remember();const ticket=epoch,files=Array.from(el.files);s.draft=null;redraw();try{if(el.id==='intake-video')s.video=await videoData(files[0]);else if(el.id==='intake-document')s.document=await imageData(files[0]);else{if(files.length+s.photos.length>3)throw Error('最多添加 3 张照片，请先移除一张。');for(const f of files)s.photos.push(await imageData(f));}}catch(err){s.error=err.message;}finally{if(active&&ticket===epoch){s.busy=false;redraw();}}}
 async function submit(e){if(e.target.id!=='intake-confirm')return;e.preventDefault();e.stopImmediatePropagation();if(s.busy)return;remember();if(!s.photos.length&&!s.video){s.error='先发一张它的照片或一段视频，再确认建档。';redraw();return;}if(!s.draft.name.trim()||s.draft.species==='unknown'){s.error='请确认它的名字和猫咪 / 狗狗类别。其他不确定的内容可以留空。';redraw();return;}if(!s.commit){const d=s.draft;s.commit={name:d.name,profile:{species:d.species,description:d.description,age:d.age,character:d.character,sex:d.sex},published:new FormData(e.target).has('published'),text:s.text,ocrText:d.ocrText,photos:s.photos.length?s.photos:[s.video.frames[0]],...(s.video?{video:s.video.dataUrl}:{})};}s.busy=true;s.error='';redraw();try{const result=await api.commitIntake(s.commit,s.key);s.busy=false;await onDone(result);}catch(err){s.error='保存未确认，草稿已保留。请重试；同一份档案不会重复建立。';s.busy=false;redraw();}}
 function bind(){if(!active)return;const stream=root.querySelector('.intake-conversation');if(stream)stream.scrollTop=stream.scrollHeight;const el=root.querySelector('#intake-hold');if(el){el.disabled=s.busy;el.oncontextmenu=e=>e.preventDefault();el.onpointerdown=e=>{if(e.button!==0||s.busy)return;e.preventDefault();el.setPointerCapture(e.pointerId);recordingStarted=false;void talk.start(e.clientY);};el.onpointermove=e=>talk.move(e.clientY);el.onpointerup=()=>void talk.end();el.onpointercancel=()=>void talk.end(true);el.onkeydown=e=>{if([' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();recordingStarted=false;void talk.start(0);}};el.onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();void talk.end();}};updateRecording();}}
 root.addEventListener('click',e=>{if(active)void action(e);});root.addEventListener('change',e=>{if(active)void change(e);});root.addEventListener('input',()=>{if(active)remember();});root.addEventListener('submit',submit,true);
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)void talk.end(true);});
 return {render,bind,reset,stop,get busy(){return !!s?.busy||talk.state.holding||talk.state.finishing;}};
}
